<?php
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/leden/service.php';
if(!$ingelogd){header('Location: ./');exit;}
if(!authHeeftCapability('committees.manage')){http_response_code(403);echo'Geen toegang tot Commissies.';exit;}
function cmEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$melding='';$meldingType='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){$melding='Sessie verlopen. Ververs de pagina.';$meldingType='fout';}
 else{$slot=dataSlotOpen();try{$data=ledenServiceLees();$oud=ledenCommissiesVolledig($data);$oudeSleutels=array_keys($oud);$nieuwe=[];$selecties=[];
   foreach($oud as $sleutel=>$bestaand){$rij=$_POST['commissie'][$sleutel]??[];if(!is_array($rij))$rij=[];if(!empty($rij['verwijderen']))continue;$naam=ledenKort($rij['naam']??$bestaand['naam'],60);if($naam==='')$naam=$bestaand['naam'];$bestuur=ledenKort($rij['bestuurslid_id']??'',40);$hoofd=ledenKort($rij['hoofd_lid_id']??'',40);$nieuwe[$sleutel]=['naam'=>$naam,'bestuurslid_id'=>$bestuur,'hoofd_lid_id'=>$hoofd];$selecties[$sleutel]=array_values(array_filter(array_map('strval',(array)($_POST['leden'][$sleutel]??[]))));}
   foreach((array)($_POST['nieuw']??[]) as $naamInvoer){$naam=ledenKort($naamInvoer,60);if($naam==='')continue;$basis=ledenCommissieSleutel($naam);if($basis==='')continue;$sleutel=$basis;$n=2;while(isset($nieuwe[$sleutel]))$sleutel=$basis.'_'.$n++;$nieuwe[$sleutel]=['naam'=>$naam,'bestuurslid_id'=>'','hoofd_lid_id'=>''];$selecties[$sleutel]=[];}
   $geldigeIds=array_column($data['leden'],'id');$bestuursIds=[];foreach($data['leden'] as $lid)if(is_array($lid)&&ledenIsBestuurslid($lid)&&empty($lid['gearchiveerd_op']))$bestuursIds[]=$lid['id'];foreach($nieuwe as $sleutel=>&$c){if(!in_array($c['bestuurslid_id'],$bestuursIds,true))$c['bestuurslid_id']='';if(!in_array($c['hoofd_lid_id'],$geldigeIds,true))$c['hoofd_lid_id']='';}unset($c);
   foreach($data['leden'] as $i=>$lid){$huidig=array_values(array_diff((array)($lid['commissies']??[]),$oudeSleutels));foreach($selecties as $sleutel=>$ids)if(in_array((string)($lid['id']??''),$ids,true))$huidig[]=$sleutel;$data['leden'][$i]['commissies']=array_values(array_unique($huidig));}
   $data['commissies']=$nieuwe;if(ledenServiceSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'commissies_bijgewerkt',count($nieuwe).' commissie(s)');$melding='Commissies opgeslagen.';$meldingType='ok';}else{$melding='Opslaan mislukt.';$meldingType='fout';}
 }finally{dataSlotDicht($slot);}}
}
$data=ledenServiceLees();$commissies=ledenCommissiesVolledig($data);$leden=array_values(array_filter($data['leden'],static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));usort($leden,static fn($a,$b)=>strcmp(ledenSorteernaam($a),ledenSorteernaam($b)));$bestuur=array_values(array_filter($leden,'ledenIsBestuurslid'));
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Commissies</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1100px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}.veld label{display:block;font-weight:700;margin-bottom:5px}.veld input,.veld select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px}.leden{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:12px}.btn{border:0;background:#3a7a77;color:#fff;padding:10px 14px;border-radius:8px;font:inherit;font-weight:750}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}.danger{color:#8b2e27}@media(max-width:800px){.grid,.leden{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Commissies</h1><p>Commissies, verantwoordelijk bestuurslid, commissiehoofd en leden op één plek.</p><?php if($melding):?><div class="melding <?=cmEsc($meldingType)?>"><?=cmEsc($melding)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=cmEsc($csrfToken)?>"><?php foreach($commissies as $sleutel=>$c):?><section class="card"><div class="grid"><div class="veld"><label>Naam</label><input name="commissie[<?=cmEsc($sleutel)?>][naam]" value="<?=cmEsc($c['naam'])?>"></div><div class="veld"><label>Verantwoordelijk bestuurslid</label><select name="commissie[<?=cmEsc($sleutel)?>][bestuurslid_id]"><option value="">Geen</option><?php foreach($bestuur as $l):?><option value="<?=cmEsc($l['id'])?>" <?=($c['bestuurslid_id']??'')===$l['id']?'selected':''?>><?=cmEsc(ledenVolledigeNaam($l))?></option><?php endforeach;?></select></div><div class="veld"><label>Commissiehoofd</label><select name="commissie[<?=cmEsc($sleutel)?>][hoofd_lid_id]"><option value="">Geen</option><?php foreach($leden as $l):?><option value="<?=cmEsc($l['id'])?>" <?=($c['hoofd_lid_id']??'')===$l['id']?'selected':''?>><?=cmEsc(ledenVolledigeNaam($l))?></option><?php endforeach;?></select></div></div><h3>Leden</h3><div class="leden"><?php foreach($leden as $l):?><label><input type="checkbox" name="leden[<?=cmEsc($sleutel)?>][]" value="<?=cmEsc($l['id'])?>" <?=in_array($sleutel,(array)($l['commissies']??[]),true)?'checked':''?>> <?=cmEsc(ledenVolledigeNaam($l))?></label><?php endforeach;?></div><p class="danger"><label><input type="checkbox" name="commissie[<?=cmEsc($sleutel)?>][verwijderen]" value="1"> Commissie verwijderen</label></p></section><?php endforeach;?><section class="card"><h2>Nieuwe commissie</h2><input name="nieuw[]" placeholder="Naam nieuwe commissie" style="padding:10px;width:min(100%,420px)"><p>Na de eerste opslag verschijnt de commissie hierboven en kunnen leden worden gekoppeld.</p></section><button class="btn" type="submit">Commissies opslaan</button></form></main></body></html>
